// Images produits Goûtstoso — extraits du fichier principal

// ── LOGO ───────────────────────────────────────────────────────
const LOGO_B64 = "data:image/jpeg;base64,";

// Pré-conversion JPEG→PNG pour jsPDF (async au chargement)
let _LOGO_PNG: string | null = null;
(()=>{
  if(typeof document==='undefined') return;
  const img = new Image();
  img.onload = () => {
    try {
      const c = document.createElement('canvas');
      c.width = img.naturalWidth; c.height = img.naturalHeight;
      const ctx = c.getContext('2d'); if(!ctx) return;
      ctx.drawImage(img, 0, 0);
      _LOGO_PNG = c.toDataURL('image/png');
    } catch(e) {}
  };
  img.src = LOGO_B64;
})();
const pdfLogo = (doc:any, mg:number) => {
  try {
    if(_LOGO_PNG) { doc.addImage(_LOGO_PNG,'PNG',mg,7,32,30); }
    else { doc.addImage(LOGO_B64,'JPEG',mg,7,32,30); }
  } catch(e) {}
};

